arguments.file_text:
namespace sv_414ca9babc3f489eac20fba191b894cf.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds per-circuit theme state.
/// In Interactive Server mode, scoped = per-circuit = per-user.
/// The circuit (and this service) survives enhanced navigations.
/// </summary>
public class ThemeService
{
    public Theme CurrentTheme { get; private set; } = Theme.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChange;

    public void SetTheme(Theme theme)
    {
        if (CurrentTheme == theme) return;
        CurrentTheme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChange?.Invoke();
    }
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService
@inject IJSRuntime JS

<span class="theme-indicator" title="Current theme">
    @GetThemeIcon() @ThemeService.CurrentTheme
</span>
<span class="accent-dot" style="background-color: @ThemeService.AccentColor;"
      title="Accent: @ThemeService.AccentColor"></span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await ApplyThemeToDocument();
        }
    }

    private async void HandleThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            await ApplyThemeToDocument();
            StateHasChanged();
        });
    }

    private async Task ApplyThemeToDocument()
    {
        var themeName = ThemeService.CurrentTheme.ToString().ToLowerInvariant();
        await JS.InvokeVoidAsync("eval", $$"""
            document.documentElement.setAttribute('data-bs-theme',
                '{{themeName}}' === 'system'
                    ? (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light')
                    : '{{themeName}}');
            document.documentElement.style.setProperty('--app-accent', '{{ThemeService.AccentColor}}');
        """);
    }

    private string GetThemeIcon() => ThemeService.CurrentTheme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

.theme-indicator {
    font-size: 0.85rem;
    margin-right: 0.5rem;
}

.accent-dot {
    display: inline-block;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    border: 1px solid rgba(0,0,0,0.2);
    vertical-align: middle;
    margin-right: 1rem;
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>
        <div class="btn-group mb-3" role="group">
            @foreach (var theme in Enum.GetValues<Theme>())
            {
                var isActive = ThemeService.CurrentTheme == theme;
                <button type="button"
                        class="btn @(isActive ? "btn-primary" : "btn-outline-secondary")"
                        @onclick="() => ThemeService.SetTheme(theme)">
                    @GetIcon(theme) @theme
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>
        <div class="d-flex align-items-center gap-3 mb-3">
            <input type="color" class="form-control form-control-color"
                   value="@ThemeService.AccentColor"
                   @onchange="OnAccentChanged"
                   title="Choose accent color" />
            <span class="text-muted">@ThemeService.AccentColor</span>
        </div>

        <div class="alert alert-info mt-3 mb-0">
            Current: <strong>@ThemeService.CurrentTheme</strong> theme,
            accent <span style="color: @ThemeService.AccentColor; font-weight: bold;">@ThemeService.AccentColor</span>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeService.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
    }

    private static string GetIcon(Theme theme) => theme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

